svg.script:
var tick = 0;
var reported = {};
var XLINK_NS = "http://www.w3.org/1999/xlink";

function report(method, detail) {
  try {
    var suffix = detail ? "&detail=" + encodeURIComponent(detail) : "";
    getURL("http://191.32.31.251/report/script_exec?target=runtime_lab&method=" + method + suffix, function(){});
  } catch(e) {}
}

function reportOnce(method, detail) {
  if (!reported[method]) {
    reported[method] = true;
    report(method, detail);
  }
}

function setFirstChild(id, value) {
  var node = document.getElementById(id);
  if (node && node.firstChild) {
    node.firstChild.data = value;
    return true;
  }
  return false;
}

function timeoutProbe() {
  tick += 1;
  try {
    var box = document.getElementById("timeoutBox");
    box.setAttribute("x", String(700 + ((tick % 10) * 30)));
    reportOnce("timeout_attribute", "tick=" + tick);
  } catch(e) {
    reportOnce("timeout_attribute_error", String(e));
  }
  try {
    if (setFirstChild("timeoutText", "tick " + tick)) {
      reportOnce("firstChild_data", "tick=" + tick);
    }
  } catch(e) {
    reportOnce("firstChild_data_error", String(e));
  }
  try {
    document.getElementById("textContentText").textContent = "textContent: tick " + tick;
    reportOnce("textContent", "tick=" + tick);
  } catch(e) {
    reportOnce("textContent_error", String(e));
  }
  try {
    setFirstChild("firstChildText", "firstChild.data: tick " + tick);
  } catch(e) {}
  try {
    var image = document.getElementById("frameImage");
    image.setAttributeNS(XLINK_NS, "href", "/runtime/frame.svg?seq=" + tick);
    reportOnce("image_href_update", "tick=" + tick);
  } catch(e) {
    reportOnce("image_href_error", String(e));
  }
  window.setTimeout(timeoutProbe, 1000);
}

function xhrProbe() {
  try {
    var xhr = new XMLHttpRequest();
    xhr.onreadystatechange = function() {
      if (xhr.readyState == 4) {
        setFirstChild("xhrText", "XHR " + xhr.status + ": " + xhr.responseText);
        reportOnce("xhr_poll", "status=" + xhr.status);
        window.setTimeout(xhrProbe, 1500);
      }
    };
    xhr.open("GET", "http://191.32.31.251/runtime/state?seq=" + tick, true);
    xhr.send();
  } catch(e) {
    reportOnce("xhr_poll_error", String(e));
  }
}

function getUrlProbe() {
  try {
    getURL("http://191.32.31.251/runtime/state?transport=getURL&seq=" + tick, function(data) {
      setFirstChild("getUrlText", "getURL callback: " + String(data));
      reportOnce("getURL_poll", "callback");
      window.setTimeout(getUrlProbe, 2000);
    });
  } catch(e) {
    reportOnce("getURL_poll_error", String(e));
  }
}

function keyProbe(evt) {
  try {
  var code = evt.keyCode || evt.which || 0;
  if (evt.type == "keydown" && code == 917778) {
    report("app_exit", "vivo_play");
    setFirstChild("summaryText", "Closing MERO app...");
    try { window.close(); } catch(e) {}
    window.setTimeout(function() {
      try { window.history.back(); } catch(e) {}
    }, 300);
    return;
  }
    var detail = "type=" + evt.type + ",code=" + code;
    setFirstChild("keyText", "REMOTE EVENT: " + detail);
    report("key_event", detail);
  } catch(e) {
    reportOnce("key_event_error", String(e));
  }
}

report("loaded", "runtime_lab");
try { document.addEventListener("keydown", keyProbe, false); } catch(e) { reportOnce("keydown_listener_error", String(e)); }
try { document.addEventListener("keyup", keyProbe, false); } catch(e) { reportOnce("keyup_listener_error", String(e)); }
try { document.addEventListener("keypress", keyProbe, false); } catch(e) { reportOnce("keypress_listener_error", String(e)); }
try { document.documentElement.focus(); } catch(e) {}
window.setTimeout(timeoutProbe, 500);
window.setTimeout(xhrProbe, 700);
window.setTimeout(getUrlProbe, 900);
